<script lang="ts">
import {ui} from '../config/copy';
let {onkey,onpeek,disabled=false}:{onkey:(key:string)=>void,onpeek:()=>void,disabled?:boolean}=$props();let pressed=$state<string>(ui.empty);function press(key:string){pressed=key;onkey(key);setTimeout(()=>pressed=ui.empty,150)}</script><div class="keyboard" aria-label={ui.keyboardLabel}>{#each [ui.keyboardTopRow,ui.keyboardMiddleRow,ui.keyboardBottomRow] as row}<div class="keyrow">{#each row.split(ui.empty) as key}<button class="key" class:pressed={pressed===key} {disabled} onclick={()=>press(key)}>{key}</button>{/each}</div>{/each}<div class="keyrow numberrow"><button class="peek" {disabled} onclick={onpeek}>{ui.peek}</button>{#each ui.keyboardNumbers.split(ui.empty) as key}<button class="number-key" {disabled} onclick={()=>press(key)}>{key}</button>{/each}</div></div>
